// Get all input items
const items = $input.all();

const monthMap = {
  January: '01',
  February: '02',
  March: '03',
  April: '04',
  May: '05',
  June: '06',
  July: '07',
  August: '08',
  September: '09',
  October: '10',
  November: '11',
  December: '12'
};

const output = items.map(item => {
  const monthName = item.json.Month || "";
  const formattedName = monthName.trim().charAt(0).toUpperCase() + monthName.trim().slice(1).toLowerCase();
  const monthNumber = monthMap[formattedName] || null;

  return {
    json: {
      Month: monthName,
      Month_Number: monthNumber // string like "01"
    }
  };
});

return output;
